import sys
import os
import json
from datetime import datetime

# Decision rules: rule_id -> fact_name -> (document, field, type)
RULES = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date", "date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "termination date": ("fda_enforcement_reports", "termination_date", "date"),
    },
}

# Entity field used to match records in each document
ENTITY_FIELDS = {
    "fda_enforcement_reports": "recall_number",
}

_doc_cache = {}

def load_document(packet_dir, doc_name):
    """Load a document by its stem (file name without extension)."""
    if doc_name in _doc_cache:
        return _doc_cache[doc_name]
    for fname in os.listdir(packet_dir):
        stem, _ = os.path.splitext(fname)
        if stem == doc_name:
            file_path = os.path.join(packet_dir, fname)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except (json.JSONDecodeError, OSError):
                continue
            if isinstance(data, dict) and "results" in data:
                records = data["results"]
            elif isinstance(data, list):
                records = data
            else:
                records = [data]
            _doc_cache[doc_name] = records
            return records
    _doc_cache[doc_name] = None
    return None

def normalize_value(value, value_type):
    """Normalize a raw field value according to its type."""
    if value_type == "date":
        if not isinstance(value, str):
            return None
        v = value.strip()
        if len(v) == 8 and v.isdigit():
            return f"{v[:4]}-{v[4:6]}-{v[6:8]}"
        if len(v) == 10 and v[4] == '-' and v[7] == '-':
            try:
                datetime.strptime(v, "%Y-%m-%d")
                return v
            except ValueError:
                return None
        for fmt in ("%Y%m%d", "%Y-%m-%d"):
            try:
                dt = datetime.strptime(v, fmt)
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                pass
        return None
    else:
        return str(value)

def get_fact_value(packet_dir, rule_id, fact_name, entity):
    """Extract the value for a single fact of a single entity."""
    if rule_id not in RULES or fact_name not in RULES[rule_id]:
        return "ABSENT"
    doc_name, field, value_type = RULES[rule_id][fact_name]
    records = load_document(packet_dir, doc_name)
    if records is None:
        return "ABSENT"
    entity_field = ENTITY_FIELDS.get(doc_name, "recall_number")
    matching = [r for r in records if str(r.get(entity_field, "")) == entity]
    if not matching:
        return "ABSENT"
    values = []
    for rec in matching:
        raw = rec.get(field, "")
        if raw is None:
            continue
        if isinstance(raw, str) and raw.strip() == "":
            continue
        norm = normalize_value(raw, value_type)
        if norm is None:
            continue
        values.append(norm)
    distinct = set(values)
    if len(distinct) == 0:
        return "ABSENT"
    elif len(distinct) == 1:
        return [values[0], doc_name]
    else:
        return "CONFLICT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)
    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})
    result = {}
    for pair in pairs:
        if "::" not in pair:
            result[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_map.get(rule_id, [])
        pair_result = {}
        for fact_name in fact_names:
            pair_result[fact_name] = get_fact_value(packet_dir, rule_id, fact_name, entity)
        result[pair] = pair_result
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

