import json
import os
import sys

def format_date(date_str):
    """Converts YYYYMMDD to YYYY-MM-DD."""
    if not date_str:
        return None
    if len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
    return date_str

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load the data file
    data_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(data_file, 'r') as f:
        data = json.load(f)

    records = data.get("results", [])

    # Map rule_id to field names based on decision rules
    rule_fields = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date"
        },
        "fda.terminated_180d": {
            "initiation date": "recall_initiation_date",
            "termination date": "termination_date"
        }
    }

    output = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::")
        facts = manifest["facts"][rule_id]

        # Find matching records by recall_number
        matching_records = [r for r in records if r.get("recall_number") == entity]

        fact_results = {}
        for fact_name in facts:
            source_field = rule_fields[rule_id][fact_name]

            # Collect non-empty values from matching records
            values = []
            for r in matching_records:
                val = r.get(source_field, "")
                if val:
                    values.append(val)

            if not values:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                formatted = format_date(values[0])
                fact_results[fact_name] = [formatted, "fda_enforcement_reports"]
            else:
                fact_results[fact_name] = "CONFLICT"

        output[pair] = fact_results

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

