import sys
import json
import os

def load_json_file(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def extract_records(data):
    """Return a list of records from a parsed JSON document."""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        if "results" in data and isinstance(data["results"], list):
            return data["results"]
        # If it's a single record dict, wrap it.
        return [data]
    return []

def normalize_date(value):
    """Convert YYYYMMDD to YYYY-MM-DD; return empty string for falsy values."""
    if not value:
        return ""
    s = str(value).strip()
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    return s

def get_values_for_fact(packet_dir, doc_name, field, entity):
    """Load the specified document and return all non-null values for the field
    among records whose recall_number matches the entity."""
    file_path = os.path.join(packet_dir, doc_name + ".json")
    if not os.path.exists(file_path):
        return []
    data = load_json_file(file_path)
    records = extract_records(data)
    values = []
    for rec in records:
        if str(rec.get("recall_number", "")).strip() == entity:
            val = rec.get(field, "")
            if val is None:
                val = ""
            values.append(val)
    return values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    manifest = load_json_file(manifest_path)

    # Mapping from (rule_id, fact_name) to (document, field)
    rule_fact_map = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "classification date": ("fda_enforcement_reports", "center_classification_date"),
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "termination date": ("fda_enforcement_reports", "termination_date"),
        },
    }

    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        facts = manifest["facts"].get(rule_id, [])
        fact_result = {}
        for fact_name in facts:
            if rule_id in rule_fact_map and fact_name in rule_fact_map[rule_id]:
                doc_name, field = rule_fact_map[rule_id][fact_name]
                raw_values = get_values_for_fact(packet_dir, doc_name, field, entity)
                norm_values = [normalize_date(v) for v in raw_values]
                non_empty = [v for v in norm_values if v]
                distinct = set(non_empty)
                if len(distinct) > 1:
                    fact_result[fact_name] = "CONFLICT"
                elif len(distinct) == 1:
                    fact_result[fact_name] = [list(distinct)[0], doc_name]
                else:
                    fact_result[fact_name] = "ABSENT"
            else:
                fact_result[fact_name] = "ABSENT"
        result[pair] = fact_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

