from datetime import datetime

# Mapping from (rule_id, fact_name) to (document_name, field_name)
RULE_FACT_MAP = {
    ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
    ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
    ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
    ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
}

# Field in fda_enforcement_reports that identifies the entity (recall number)
IDENTIFIER_FIELD = "recall_number"


def normalize_date(value):
    """Convert a date string to YYYY-MM-DD if possible."""
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    # YYYYMMDD
    if re.fullmatch(r"\d{8}", s):
        return f"{s[:4]}-{s[4:6]}-{s[6:]}"
    # Already YYYY-MM-DD
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        return s
    # Try a few common formats
    for fmt in ("%m/%d/%Y", "%m/%d/%y", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s


def normalize_value(value, fact_name):
    if "date" in fact_name.lower():
        return normalize_date(value)
    return value


def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory."""
    for ext in (".json", ".JSON", ""):
        path = os.path.join(packet_dir, doc_name + ext)
        if os.path.isfile(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    return None


def extract_records(doc_data):
    """Extract the list of records from a loaded JSON document."""
    if isinstance(doc_data, list):
        return doc_data
    if isinstance(doc_data, dict):
        if "results" in doc_data and isinstance(doc_data["results"], list):
            return doc_data["results"]
    return []


def get_values_for_entity(doc_data, entity, field):
    """Return all non-empty values for the given field from records matching the entity."""
    records = extract_records(doc_data)
    values = []
    for rec in records:
        if isinstance(rec, dict) and rec.get(IDENTIFIER_FIELD) == entity:
            if field in rec:
                v = rec[field]
                if v is not None and str(v).strip() != "":
                    values.append(v)
    return values


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    doc_cache = {}
    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        fact_results = {}

        for fact_name in fact_names:
            key = (rule_id, fact_name)
            if key not in RULE_FACT_MAP:
                fact_results[fact_name] = "ABSENT"
                continue

            doc_name, field = RULE_FACT_MAP[key]
            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)
            doc_data = doc_cache[doc_name]

            if doc_data is None:
                fact_results[fact_name] = "ABSENT"
                continue

            raw_values = get_values_for_entity(doc_data, entity, field)
            if not raw_values:
                fact_results[fact_name] = "ABSENT"
                continue

            normalized = [normalize_value(v, fact_name) for v in raw_values]
            unique = set(normalized)
            if len(unique) == 1:
                fact_results[fact_name] = [normalized[0], doc_name]
            else:
                fact_results[fact_name] = "CONFLICT"

        output[pair] = fact_results

    print(json.dumps(output, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

