import json
import os
import sys

def convert_date(date_str):
    """Convert YYYYMMDD to YYYY-MM-DD"""
    if not date_str or (isinstance(date_str, str) and date_str.strip() == ""):
        return None
    if isinstance(date_str, str) and len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[0:4]}-{date_str[4:6]}-{date_str[6:8]}"
    return str(date_str)

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(fda_path, 'r') as f:
        fda_data = json.load(f)

    records_by_recall = {}
    for record in fda_data.get("results", []):
        recall_number = record.get("recall_number", "")
        if recall_number not in records_by_recall:
            records_by_recall[recall_number] = []
        records_by_recall[recall_number].append(record)

    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    doc_name = "fda_enforcement_reports"

    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"][rule_id]

        pair_result = {}
        records = records_by_recall.get(entity, [])

        for fact_name in facts:
            field = fact_to_field.get(fact_name)
            if field is None:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for record in records:
                raw_value = record.get(field)
                if raw_value is None:
                    continue
                converted = convert_date(raw_value)
                if converted is not None:
                    values.append(converted)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [values[0], doc_name]
            else:
                unique_values = set(values)
                if len(unique_values) == 1:
                    pair_result[fact_name] = [values[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

